const codes={RULE_WORKER_START_ERROR:'Execution worker could not start',RULE_FIELD_MISSING:'Configured field is missing',RULE_TARGET_EXISTS:'Rename target already exists',RULE_CONFIG_INVALID:'Rule configuration is invalid',RULE_EXECUTION_ERROR:'Rule execution failed',RULE_PROCESS_EXIT:'Worker stopped unexpectedly',RULE_VALIDATION_FAILED:'Data failed the rule checks',RULE_NUMERIC_INVALID:'Invalid numeric values',RULE_DATE_INVALID:'Invalid date values',VALIDATION_REQUIRED:'Required values are missing',VALIDATION_RANGE:'Values failed the allowed range',VALIDATION_PATTERN:'Values failed the text pattern',VALIDATION_DUPLICATE:'Duplicate values detected',RULE_RETRY_LIMIT:'Rule failed three attempts',INPUT_PARSE_ERROR:'Input file could not be parsed',JOB_TIMEOUT:'Job exceeded the processing time limit',JOB_CANCELLED_BY_USER:'Cancelled by user',JOB_SERVER_RESTARTED:'Server stopped before completion',JOB_INTERNAL_ERROR:'Job processing encountered an internal error'};
