function currentWeek(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const d=new Date(Date.UTC(+parts.year,+parts.month-1,+parts.day));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const first=new Date(Date.UTC(d.getUTCFullYear(),0,1));return `${d.getUTCFullYear()}-W${String(Math.ceil((((d-first)/86400000)+1)/7)).padStart(2,'0')}`;}
async function api(path,options){const response=await fetch(`${API}${path}`,options);const data=await response.json();if(!response.ok||!data.success){const failure=new Error(data.error||'Request failed.');failure.report=data.report;failure.status=response.status;throw failure;}return data;}
