 return <section aria-label="Batch receipt metrics" className="mb-6 space-y-4"><div className="grid grid-cols-2 md:grid-cols-3 gap-3">{[['Rows Received',count(m.rowsReceived)],['Rows Count (after data cleaning)',count(m.rowsAfterCleaning)],['Stores Received',count(m.storesReceived)],['Store Table + New Stores',count(m.storeTotalIncludingNew)],['File Size',bytes(m.fileSizeBytes)],['Deviated File Size',deviation]].map(([label,value])=><div key={label} className="rounded border border-slate-700 bg-slate-900 p-3"><p className="text-xs text-slate-400">{label}</p><p className="mt-2 text-sm font-semibold">{value}</p></div>)}</div><p className="text-xs text-slate-400">File size compared with {m.previousPeriod||'previous ISO week'}: {bytes(m.previousFileSizeBytes)}. Counts use the input Store IDs and the store table at job start. {m.storeComparisonNote}</p>{m.rowsWithoutStoreId>0&&<p className="text-xs text-amber-300">{m.rowsWithoutStoreId} rows have no Store ID.</p>}<div className="grid md:grid-cols-2 gap-4">{[['New Stores',m.newStores,'text-amber-300'],['Missing Stores',m.missingStores,'text-rose-300']].map(([label,stores,color])=><div key={label} className="rounded border border-slate-700 p-3"><h4 className={`text-sm font-semibold ${color}`}>{label}: {stores==null?'Unavailable':stores.length}</h4>{stores?.length>0&&<ul className="mt-2 text-xs space-y-1 max-h-40 overflow-auto">{stores.map(store=><li key={store.key}>{store.key} · {store.name}</li>)}</ul>}{stores?.length===0&&<p className="mt-2 text-xs text-slate-400">None flagged.</p>}</div>)}</div><p className="text-xs text-slate-400">New stores are added only through Review New Stores → Approve New Stores. Approve Job is separate. Missing stores remain in the store table.{m.newStoresApprovedCount!=null&&` New stores approved: ${m.newStoresApprovedCount}.`}{m.newStoresAddedOnApproval!=null&&` Added by earlier job-approval workflow: ${m.newStoresAddedOnApproval}.`}</p></section>;
}

