 const [error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[audit,setAudit]=useState(null),[configurationJob,setConfigurationJob]=useState(null),[storeReviewJob,setStoreReviewJob]=useState(null),[preprocessing,setPreprocessing]=useState(null),[reprocessJob,setReprocessJob]=useState(null),[reprocessPeriod,setReprocessPeriod]=useState('');
 const [page,setPage]=useState(0),[filter,setFilter]=useState('');
 async function refresh(){const data=await api('/batches');setJobs(data.jobs);setActive(data.active);}
