 async function start(e){e.preventDefault();setError('');if(!file){setError('Select a data file.');return;}if(file.size>50*1024*1024){setError('Batch files must be below the 50 MB upload limit.');return;}setBusy(true);const form=new FormData();form.append('file',file);form.append('retailerId',retailerId);form.append('period',period);form.append('storeIdField',storeIdField);try{if(!preprocessing?.ready){const serial=checkRequest.current;const checked=await api('/batches/preprocessing',{method:'POST',body:form});if(serial===checkRequest.current)setPreprocessing(checked.report);return;}form.append('expectedConfigurationHash',preprocessing.configurationHash);await api('/batches',{method:'POST',body:form});setPreprocessing(null);setOpen(false);setFile(null);setNotice('Batch started. Its current progress appears below.');await refresh();}catch(e){setError(e.message);if(e.report)setPreprocessing(e.status===409?null:e.report);}finally{setBusy(false);}}
 async function action(id,type){if(type==='cancel'&&!window.confirm('Cancel this job? The cancelled job will have no End Time or Audit Logs. Other runs and their audits are retained.'))return;setBusy(true);setError('');try{await api(`/batches/${id}/${type}`,{method:'POST'});setNotice(type==='reprocess'?'Reprocessing started using the latest saved retailer rules. This run creates a new log row; previous runs remain.':type==='approve'?'Job approved.':'Job cancelled.');await refresh();}catch(e){setError(e.message);if(e.report)setPreprocessing(e.status===409?null:e.report);}finally{setBusy(false);}}
