 return <section aria-label="Preprocessing results" className="rounded border border-slate-600 bg-slate-950 p-4 space-y-3"><h4 className={report.ready?'text-emerald-300 font-semibold':'text-rose-300 font-semibold'}>{report.ready?'Preprocessing passed — ready to start':'Preprocessing blocked — fix errors and check again'}</h4><p className="text-xs text-slate-400">{report.filename} · {report.period} · {report.rowsReceived??'Unavailable'} rows · {report.fileSizeBytes?.toLocaleString()} bytes</p>{report.columns?.length>0&&<p className="text-xs text-slate-400">Fields: {report.columns.join(', ')}</p>}{report.issues?.length>0&&<div className="overflow-auto"><table className="w-full text-left text-xs"><thead><tr>{['Rule','Code','Fix / Details'].map(h=><th key={h} className="p-2">{h}</th>)}</tr></thead><tbody>{report.issues.map((issue,i)=><tr key={i} className="border-t border-slate-700 text-rose-300"><td className="p-2">{issue.sequence?`${issue.sequence}. ${issue.ruleName}`:'File / Setup'}</td><td className="p-2 font-mono">{issue.code}</td><td className="p-2">{issue.message}</td></tr>)}</tbody></table></div>}{report.warnings?.length>0&&<div className="text-xs text-amber-300"><p className="font-semibold">Warnings (do not block execution)</p><ul className="list-disc pl-5 mt-2 space-y-1">{report.warnings.map((w,i)=><li key={i}>{w}</li>)}</ul></div>}<p className="text-xs text-slate-400">This checks file structure and configuration. Data validation runs during processing and can still fail. No job has started yet.</p></section>;
}

